\coordinate (P) at (5,0);
\coordinate (T1) at (1.8,2.4);
\coordinate (T2) at (1.8,-2.4);
\draw (O) circle (3);
\fill (O) circle (1.5pt);
\node[left] at (O) {$O$};
\draw (O) -- (T1);
\draw (O) -- (T2);
\draw[tickmark] (P) -- (T1) node[midway, above left] {$9\text{ cm}$};
\draw[tickmark] (P) -- (T2);
